import numpy as np
from weight_utils import weight
X={i:np.load(f'acts/inspect_{i}.npy').astype(float) for i in range(11)}
for b in [9,10]:
 print('BLOCK',b)
 for i,n in [(3,4),(4,4),(5,4),(6,4),(7,4)]:
  Z=X[i].reshape(-1,n,19,640)
  if i==3:p=Z[:,[0,2]].reshape(-1,19,640);neg=Z[:,[1,3]].reshape(-1,19,640)
  elif i in [4,5]:p=Z[:,1];neg=Z[:,2]
  else:p=Z[:,[1,2]].reshape(-1,19,640);neg=Z[:,3]
  d=neg[:,b+1].mean(0)-p[:,b+1].mean(0)
  dm=(neg[:,b+1]-neg[:,b]).mean(0)-(p[:,b+1]-p[:,b]).mean(0)
  print('sample',i,'state shift',round(np.linalg.norm(d),2),'increment shift',round(np.linalg.norm(dm),2),'cos',round(d@dm/(np.linalg.norm(d)*np.linalg.norm(dm)),3))
  for module,ln in [('self_attn.o_proj','post_attention_layernorm'),('mlp.down_proj','post_feedforward_layernorm')]:
   g=weight(f'model.layers.{b}.{ln}.weight')+1
   print(module,'shift/norm weights norm',round(np.linalg.norm(d/g),2),'lowgamma mass',round(np.linalg.norm(d[np.abs(g)<1])/np.linalg.norm(d),3))
 # All data source unedited increments and means.
 for i in [0,1,3,4,5,6,7,8,9,10]:
  z=X[i][:,b+1]-X[i][:,b]
  print('increment',i,'mean norm',round(np.linalg.norm(z.mean(0)),2),'std norm',round(np.linalg.norm(z-z.mean(0),axis=1).mean(),2))
